func WriteExperiencePatternAction(ctx context.Context, params ActionParams) (interface{}, error) {
    entry := datahelpers.ExtractNestedFieldMap(params.CollectedData, field)
    problems := validateExperiencePatternShape(entry)          // shape, contract triggers, status-not-writable
    validation = ValidateExperienceCriteria(tmpl, asMap(entry["binding_schema"]),
        entry["contract"], entry["states"], entry["data_contract"],
        entry["degraded_states"], entry["entry_points"])       // extras close placeholders in EVERY document
    for _, e := range validation.Errors { problems = append(problems, ...) }
    if len(problems) > 0 { return nil, fmt.Errorf("refused, %d problem(s): %s", ...) }

    missing, err := missingExperienceInvariants(ctx, params.DB, entry["requires_invariant"])
    if len(missing) > 0 { return nil, fmt.Errorf("requires invariant(s) that do not exist: %s", ...) }

    tx := params.DB.BeginTx(...)
    tx.QueryRow(`SELECT status, to_jsonb(p) FROM experience_patterns p WHERE name = $1 FOR UPDATE`, name)
    if prevStatus == "approved" || prevStatus == "proven" {
        changedFields = changedExperienceContractFields(prev, entry)
        demoted = len(changedFields) > 0
    }
    // status is NEVER taken from the entry: insert 'draft'; on conflict keep it
    // unless a clause-bearing field changed, in which case set 'draft'.
    INSERT INTO experience_patterns (...) VALUES (...) ON CONFLICT (name) DO UPDATE SET ...
    // demotion is logged at WARN with the field list: an approval that quietly
    // stops applying is exactly what this rule exists to prevent.
}

